import multiprocessing as mp, time
def work(_):
    buf = bytearray(250*1024*1024)
    for i in range(0, len(buf), 4096): buf[i] = 1
    t = time.process_time()
    while time.process_time() - t < 1.5: pass
if __name__ == "__main__":
    ps = [mp.Process(target=work, args=(i,)) for i in range(3)]
    for p in ps: p.start()
    for p in ps: p.join()
